"use strict";(globalThis.webpackChunkp2d_control_tower_docs=globalThis.webpackChunkp2d_control_tower_docs||[]).push([[398],{1953(a){a.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"adminSidebar":[{"type":"link","href":"/msa-station-docs/id/","label":"Panduan Pengguna MSA Station TMS","docId":"intro","unlisted":false},{"type":"category","label":"\ud83d\ude80 Getting Started","items":[{"type":"link","href":"/msa-station-docs/id/getting-started/dashboard","label":"Dasbor","docId":"getting-started/dashboard","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"\ud83d\uddc2\ufe0f Master Data","items":[{"type":"link","href":"/msa-station-docs/id/master-data/shipper","label":"Shipper (Pengirim)","docId":"master-data/shipper","unlisted":false},{"type":"link","href":"/msa-station-docs/id/master-data/consignee","label":"Consignee (Penerima)","docId":"master-data/consignee","unlisted":false},{"type":"link","href":"/msa-station-docs/id/master-data/contract","label":"Contract (Kontrak)","docId":"master-data/contract","unlisted":false},{"type":"link","href":"/msa-station-docs/id/master-data/price","label":"Price (Harga)","docId":"master-data/price","unlisted":false},{"type":"link","href":"/msa-station-docs/id/master-data/price-check","label":"Price Check (Cek Harga)","docId":"master-data/price-check","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"\ud83d\udce6 AWB Data","items":[{"type":"link","href":"/msa-station-docs/id/awb-data/upload-data","label":"Upload Data","docId":"awb-data/upload-data","unlisted":false},{"type":"link","href":"/msa-station-docs/id/awb-data/entry-data","label":"Entry Data (Booking Order)","docId":"awb-data/entry-data","unlisted":false},{"type":"link","href":"/msa-station-docs/id/awb-data/delivery-order","label":"Delivery Order (Manifest)","docId":"awb-data/delivery-order","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"\ud83d\ude9a Driver","items":[{"type":"link","href":"/msa-station-docs/id/driver/order-driver","label":"Order Driver","docId":"driver/order-driver","unlisted":false},{"type":"link","href":"/msa-station-docs/id/driver/booking-driver","label":"Booking Driver","docId":"driver/booking-driver","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"\ud83d\udccd Tracking","items":[{"type":"link","href":"/msa-station-docs/id/tracking/live-tracking","label":"Live Tracking","docId":"tracking/live-tracking","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"\ud83d\udcca Report Data","items":[{"type":"link","href":"/msa-station-docs/id/report-data/print-report-by-date","label":"Print Report By Date","docId":"report-data/print-report-by-date","unlisted":false},{"type":"link","href":"/msa-station-docs/id/report-data/print-sp","label":"Print SP","docId":"report-data/print-sp","unlisted":false},{"type":"link","href":"/msa-station-docs/id/report-data/invoices","label":"Invoices (Faktur)","docId":"report-data/invoices","unlisted":false},{"type":"link","href":"/msa-station-docs/id/report-data/update-status","label":"Update Status","docId":"report-data/update-status","unlisted":false}],"collapsed":true,"collapsible":true}]},"docs":{"awb-data/delivery-order":{"id":"awb-data/delivery-order","title":"Delivery Order (Manifest)","description":"Layar Delivery Order mengelola catatan tingkat manifest yang digunakan untuk menghasilkan dokumen pengiriman. Layar ini membangun dari data booking dan menambahkan detail kepabeanan/pemberitahuan (CN, Pemberitahu) yang diperlukan untuk mengirim dan mendokumentasikan pengiriman.","sidebar":"adminSidebar"},"awb-data/entry-data":{"id":"awb-data/entry-data","title":"Entry Data (Booking Order)","description":"Layar Entry Data adalah tempat Anda membuat dan mengelola Shipping Instruction / Job Order (JO) untuk booking domestik. Ini adalah catatan operasional inti yang menyatukan shipper, consignee, rute, detail kargo, dan harga.","sidebar":"adminSidebar"},"awb-data/upload-data":{"id":"awb-data/upload-data","title":"Upload Data","description":"Modul Upload Data memungkinkan Anda mengimpor berkas pengiriman/manifest secara massal dengan cara menyeret dan menjatuhkannya (drag and drop) ke dalam sistem. Berkas dikelompokkan berdasarkan kategori manifest agar sistem tahu cara memproses setiap unggahan.","sidebar":"adminSidebar"},"driver/booking-driver":{"id":"driver/booking-driver","title":"Booking Driver","description":"Modul Booking Driver melacak status sisi-driver dari setiap order yang dikirim. Di sinilah progres driver \u2014 beserta bukti pickup/pengiriman \u2014 dicatat terhadap sebuah booking.","sidebar":"adminSidebar"},"driver/order-driver":{"id":"driver/order-driver","title":"Order Driver","description":"Modul Order Driver adalah tempat Anda membuat order pickup/pengiriman dan menugaskannya ke kendaraan serta driver. Modul ini mengubah booking menjadi tugas pengiriman yang dapat dilaksanakan.","sidebar":"adminSidebar"},"getting-started/dashboard":{"id":"getting-started/dashboard","title":"Dasbor","description":"Setelah berhasil login, Anda akan masuk ke Dasbor \u2014 panel kontrol utama MSA Station TMS. Halaman ini memberikan ringkasan aktivitas harian dan akses cepat ke seluruh modul.","sidebar":"adminSidebar"},"intro":{"id":"intro","title":"Panduan Pengguna MSA Station TMS","description":"MSA Station TMS adalah Transport Management System yang dioperasikan oleh MSA Kargo. Platform ini menyediakan pusat pengelolaan delivery order, penugasan driver, pelacakan pengiriman, dan operasional logistik last-mile.","sidebar":"adminSidebar"},"master-data/consignee":{"id":"master-data/consignee","title":"Consignee (Penerima)","description":"Modul Consignee menyimpan data master setiap penerima (pihak yang menerima barang). Menyimpan consignee di sini memungkinkan Anda memilihnya secara instan saat membuat booking dan delivery order.","sidebar":"adminSidebar"},"master-data/contract":{"id":"master-data/contract","title":"Contract (Kontrak)","description":"Modul Contract mencatat perjanjian layanan yang menjadi dasar penetapan harga. Sebuah kontrak mendefinisikan perjanjian bernama beserta masa berlakunya; entri harga (lihat Price) kemudian dilampirkan ke kontrak tersebut.","sidebar":"adminSidebar"},"master-data/price":{"id":"master-data/price","title":"Price (Harga)","description":"Modul Price menentukan tarif untuk setiap kontrak berdasarkan rute (asal \u2192 tujuan), produk, dan jenis kontrak. Tarif ini digunakan secara otomatis saat menghitung biaya dan harga jual pengiriman pada saat booking.","sidebar":"adminSidebar"},"master-data/price-check":{"id":"master-data/price-check","title":"Price Check (Cek Harga)","description":"Alat Price Check memungkinkan Anda mencari tarif yang berlaku untuk suatu kontrak dan rute dengan cepat tanpa menelusuri seluruh daftar harga. Berguna saat memberi penawaran ke pelanggan atau memverifikasi biaya.","sidebar":"adminSidebar"},"master-data/shipper":{"id":"master-data/shipper","title":"Shipper (Pengirim)","description":"Modul Shipper menyimpan data master setiap pengirim (consignor) yang Anda layani. Setelah shipper disimpan di sini, Anda dapat memilihnya dengan cepat saat membuat booking atau shipping instruction tanpa perlu mengetik ulang detailnya.","sidebar":"adminSidebar"},"report-data/invoices":{"id":"report-data/invoices","title":"Invoices (Faktur)","description":"Modul Invoices menampilkan seluruh dokumen tagihan dan memungkinkan Anda meninjau, mencetak, serta melacak status pembayaran setiap faktur.","sidebar":"adminSidebar"},"report-data/print-report-by-date":{"id":"report-data/print-report-by-date","title":"Print Report By Date","description":"Alat Print Report By Date menghasilkan laporan manifest untuk seluruh pengiriman yang berangkat pada tanggal tertentu, siap untuk dicetak.","sidebar":"adminSidebar"},"report-data/print-sp":{"id":"report-data/print-sp","title":"Print SP","description":"Alat Print SP memungkinkan Anda mencari Job Order tertentu dan mencetak dokumen SP (Surat Perintah) miliknya.","sidebar":"adminSidebar"},"report-data/update-status":{"id":"report-data/update-status","title":"Update Status","description":"Layar Update Status memungkinkan setiap peran operasional memajukan status pengiriman seiring pergerakannya melalui alur. Tersedia layar khusus per peran agar tanggung jawab tetap jelas, ditambah tampilan All untuk supervisor.","sidebar":"adminSidebar"},"tracking/live-tracking":{"id":"tracking/live-tracking","title":"Live Tracking","description":"Modul Live Tracking menampilkan lokasi pengiriman dan driver Anda secara real-time pada peta interaktif.","sidebar":"adminSidebar"}}}}')}}]);